+P('[Pauschbetrag]',`<div class="k"><b class="${pc>90?'neg p':'pos'}">${eur(use)}</b><span>von ${eur(pb)} genutzt · ${eur(left)} frei (ETF/Aktien)</span></div><div class="bar"><i style="width:${pc}%"></i></div><div class="mut">Kapitalerträge nach Teilfreistellung: ${eur(gc)} → Steuer ${eur(taxK)}</div><div class="mut" style="margin-top:6px">Krypto/Gold (Haltefrist &lt; 1 J.): ${eur(gp)} → ${gp>=1000?'Steuer ca. '+eur(taxP):'unter Freigrenze 1.000 €, steuerfrei'}</div><div class="row">${inp('Pauschbetrag €','pb',pb,1)}${inp('Abgeltung %','kt',kt,.001)}${inp('Pers. Satz %','ps',ps,1)}</div>`)
